import{_ as e,a as o,o as d,a6 as r}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Product Type Sub-Resources (Product Types tag)","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-variants","title":"Variants — for a configurable product","description":"List the child variant products of a configurable parent. Each variant is a `simple` product with the same card-level fields as the listing endpoint.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/23/variants\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 24,\\n    \\"sku\\": \\"LUGGAGE-RED\\",\\n    \\"type\\": \\"simple\\",\\n    \\"name\\": \\"Luggage bags-Red\\",\\n    \\"price\\": 100,\\n    \\"formattedPrice\\": \\"$100.00\\",\\n    \\"...\\": \\"...\\"\\n  }\\n]\\n","commonErrors":[{"error":"404 Not Found","cause":"Parent product `{productId}` doesn\'t exist or isn\'t configurable","solution":"Use `GET /api/shop/products?type=configurable` to find configurable products."}]},{"id":"list-booking-products","title":"Booking Products — config for a product","description":"Booking-specific configuration row(s) for a `booking`-type product. The `type` field on each row tells you which slot helper drives availability — pair it with [Booking Slots](/api/rest-api/shop/products/get-booking-slots) for a date.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2507/booking-products\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"type\\": \\"default\\",\\n    \\"qty\\": 150,\\n    \\"location\\": \\"Noida, Uttar Pradesh\\",\\n    \\"showLocation\\": 0,\\n    \\"availableFrom\\": \\"2026-04-06T12:00:00+05:30\\",\\n    \\"availableTo\\": \\"2026-12-31T12:00:00+05:30\\",\\n    \\"createdAt\\": \\"2026-04-03T00:24:30+05:30\\",\\n    \\"updatedAt\\": \\"2026-04-06T21:09:47+05:30\\",\\n    \\"slots\\": {\\n      \\"bookingType\\": \\"one\\",\\n      \\"sameSlotAllDays\\": null,\\n      \\"slots\\": [\\n        { \\"id\\": \\"1\\", \\"from\\": \\"12:00\\", \\"to\\": \\"18:00\\", \\"from_day\\": \\"1\\", \\"to_day\\": \\"1\\" },\\n        { \\"id\\": \\"2\\", \\"from\\": \\"12:00\\", \\"to\\": \\"18:00\\", \\"from_day\\": \\"2\\", \\"to_day\\": \\"2\\" }\\n      ]\\n    }\\n  }\\n]\\n"},{"id":"get-booking-product","title":"Booking Products — single by ID","description":"Fetch a single booking config row by its global ID (the value found in `bookingProducts[].id` on the parent product). Includes IRI references to the type-specific slot config.\\n","request":"curl -X GET \\"http://localhost/api/shop/booking-products/1\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 1,\\n  \\"type\\": \\"default\\",\\n  \\"qty\\": 150,\\n  \\"location\\": \\"Noida, Uttar Pradesh\\",\\n  \\"showLocation\\": 0,\\n  \\"availableEveryWeek\\": null,\\n  \\"availableFrom\\": \\"2026-04-06T12:00:00+05:30\\",\\n  \\"availableTo\\": \\"2026-12-31T12:00:00+05:30\\",\\n  \\"slots\\": { \\"bookingType\\": \\"one\\", \\"slots\\": [ \\"...\\" ] },\\n  \\"defaultSlot\\": \\"/api/shop/booking_product_default_slots/1\\",\\n  \\"appointmentSlot\\": null,\\n  \\"rentalSlot\\": null,\\n  \\"tableSlot\\": null,\\n  \\"eventTickets\\": []\\n}\\n"},{"id":"get-booking-default-slot","title":"Booking Slot Config — `default` type","description":"Static slot configuration for a `default`-type booking product. The `slots` field is a **JSON string** — parse it client-side. For runtime availability on a specific date, use [Booking Slots](/api/rest-api/shop/products/get-booking-slots).\\n","request":"curl -X GET \\"http://localhost/api/shop/booking_product_default_slots/1\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 1,\\n  \\"bookingType\\": \\"one\\",\\n  \\"duration\\": null,\\n  \\"breakTime\\": null,\\n  \\"slots\\": \\"[{\\\\\\"id\\\\\\": \\\\\\"1\\\\\\", \\\\\\"to\\\\\\": \\\\\\"18:00\\\\\\", \\\\\\"from\\\\\\": \\\\\\"12:00\\\\\\", \\\\\\"to_day\\\\\\": \\\\\\"1\\\\\\", \\\\\\"from_day\\\\\\": \\\\\\"1\\\\\\"}]\\"\\n}\\n"},{"id":"get-booking-event-ticket","title":"Booking Slot Config — `event` ticket","description":"Single ticket row for an `event`-type booking product. Each ticket is its own purchasable line with its own price, qty, and locale-specific `name` / `description`.\\n","request":"curl -X GET \\"http://localhost/api/shop/booking_product_event_tickets/7\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 7,\\n  \\"bookingProductId\\": 2,\\n  \\"price\\": 120,\\n  \\"qty\\": 1500,\\n  \\"specialPrice\\": 115,\\n  \\"specialPriceFrom\\": \\"2026-04-06 12:00:00\\",\\n  \\"specialPriceTo\\": \\"2026-04-30 12:00:00\\",\\n  \\"formattedPrice\\": \\"$120.00\\",\\n  \\"formattedSpecialPrice\\": \\"$115.00\\",\\n  \\"translations\\": [\\"/api/booking_product_event_ticket_translations/7\\"],\\n  \\"translation\\": \\"/api/booking_product_event_ticket_translations/7\\"\\n}\\n"},{"id":"list-bundle-options","title":"Bundle Options — for a bundle product","description":"Decision groups for a `bundle`-type product. Each option has its member products as IRIs (under `bundleOptionProducts[]`) — dereference for full member details.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2517/bundle-options\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"type\\": \\"radio\\",\\n    \\"isRequired\\": 1,\\n    \\"sortOrder\\": 0,\\n    \\"product\\": \\"/api/shop/products/2517\\",\\n    \\"bundleOptionProducts\\": [\\"/api/shop/product-bundle-option-products/1\\"],\\n    \\"translation\\": \\"/api/shop/product_bundle_option_translations/1\\",\\n    \\"translations\\": [\\n      \\"/api/shop/product_bundle_option_translations/5\\",\\n      \\"/api/shop/product_bundle_option_translations/1\\"\\n    ]\\n  }\\n]\\n"},{"id":"list-bundle-option-products","title":"Bundle Option Products","description":"Member products inside a bundle option (the actual SKUs the customer can pick). Each row links back to its parent `bundleOption` and its `product`.\\n","request":"curl -X GET \\"http://localhost/api/shop/product-bundle-option-products?per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 12\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 6\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"qty\\": 1,\\n    \\"isUserDefined\\": 1,\\n    \\"isDefault\\": 1,\\n    \\"sortOrder\\": 0,\\n    \\"bundleOption\\": \\"/api/shop/product_bundle_options/1\\",\\n    \\"product\\": \\"/api/shop/products/2512\\"\\n  }\\n]\\n"},{"id":"list-grouped-products","title":"Grouped Products — members of a grouped product","description":"Associated products inside a `grouped`-type product. The customer can add any subset to the cart with their own quantities.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2516/grouped-products\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  { \\"id\\": 1, \\"qty\\": 1, \\"sortOrder\\": 0, \\"product\\": \\"/api/shop/products/2516\\", \\"associatedProduct\\": \\"/api/shop/products/2512\\" },\\n  { \\"id\\": 2, \\"qty\\": 1, \\"sortOrder\\": 1, \\"product\\": \\"/api/shop/products/2516\\", \\"associatedProduct\\": \\"/api/shop/products/2514\\" }\\n]\\n"},{"id":"list-downloadable-links","title":"Downloadable Links — for a downloadable product","description":"Purchasable downloadable links attached to a `downloadable`-type product. Each link carries its own price, sample file, and download limit.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2506/downloadable-links\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 2,\\n    \\"url\\": \\"https://example.com/textbook.pdf\\",\\n    \\"type\\": \\"url\\",\\n    \\"price\\": 69,\\n    \\"sampleFile\\": \\"product_downloadable_links/2506/...pdf\\",\\n    \\"sampleFileName\\": \\"Personal Finance.pdf\\",\\n    \\"sampleType\\": \\"file\\",\\n    \\"downloads\\": 10,\\n    \\"sortOrder\\": 0,\\n    \\"createdAt\\": \\"2026-04-03T00:14:55+05:30\\",\\n    \\"updatedAt\\": \\"2026-04-03T00:14:55+05:30\\",\\n    \\"formattedPrice\\": \\"$69.00\\",\\n    \\"fileUrl\\": \\"http://localhost/storage/\\",\\n    \\"sampleFileUrl\\": \\"http://localhost/api/downloadable/download-sample/link/2\\",\\n    \\"product\\": \\"/api/shop/products/2506\\",\\n    \\"translation\\": \\"/api/shop/product_downloadable_link_translations/2\\",\\n    \\"translations\\": [\\n      \\"/api/shop/product_downloadable_link_translations/2\\",\\n      \\"/api/shop/product_downloadable_link_translations/3\\"\\n    ]\\n  }\\n]\\n"},{"id":"list-downloadable-samples","title":"Downloadable Samples — for a downloadable product","description":"Free preview files attached to a downloadable product. Listed separately from the paid links so the customer can preview before buying.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2506/downloadable-samples\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"file\\": \\"product_downloadable_links/2506/....pdf\\",\\n    \\"fileName\\": \\"document.pdf\\",\\n    \\"type\\": \\"file\\",\\n    \\"sortOrder\\": 0,\\n    \\"createdAt\\": \\"2026-04-03T00:14:55+05:30\\",\\n    \\"updatedAt\\": \\"2026-04-03T00:14:55+05:30\\",\\n    \\"fileUrl\\": \\"http://localhost/api/downloadable/download-sample/sample/1\\",\\n    \\"product\\": \\"/api/shop/products/2506\\",\\n    \\"translation\\": \\"/api/shop/product_downloadable_sample_translations/1\\",\\n    \\"translations\\": [\\"/api/shop/product_downloadable_sample_translations/1\\"]\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/shop/products/product-type-subresources.md","filePath":"api/rest-api/shop/products/product-type-subresources.md","lastUpdated":1787725411000}'),a={name:"api/rest-api/shop/products/product-type-subresources.md"};function n(i,t,s,c,l,p){return d(),o("div",null,t[0]||(t[0]=[r('<h1 id="product-type-sub-resources-product-types-tag" tabindex="-1">Product Type Sub-Resources (<code>Product Types</code> tag) <a class="header-anchor" href="#product-type-sub-resources-product-types-tag" aria-label="Permalink to &quot;Product Type Sub-Resources (`Product Types` tag)&quot;">​</a></h1><p>The endpoints in this group expose the type-specific configuration of products that aren&#39;t just <code>simple</code>: configurable variants, booking slots, bundle option groups, grouped associations, downloadable links and samples. Most of this data is also inlined on <a href="/api/rest-api/shop/products/get-product.html">Single Product</a> — these dedicated endpoints exist for clients that need just one slice.</p><h2 id="url-naming-is-not-uniform" tabindex="-1">URL naming is not uniform <a class="header-anchor" href="#url-naming-is-not-uniform" aria-label="Permalink to &quot;URL naming is not uniform&quot;">​</a></h2><p>Root URLs in this group use two different separators, so a path cannot be guessed from the resource name:</p><table tabindex="0"><thead><tr><th>Separator</th><th>Endpoints</th></tr></thead><tbody><tr><td>Dashed</td><td><code>*-bundle-option-products</code>, <code>*-downloadable-links</code>, <code>*-downloadable-samples</code>, <code>booking-products</code>, <code>booking-slots</code></td></tr><tr><td>Underscored</td><td><code>product_bundle_options</code>, <code>product_grouped_products</code>, <code>booking_product_default_slots</code>, <code>booking_product_appointment_slots</code>, <code>booking_product_rental_slots</code>, <code>booking_product_event_tickets</code>, <code>booking_product_table_slots</code>, and every <code>*_translations</code> endpoint</td></tr></tbody></table><p>Copy the URL from the parent resource&#39;s IRI rather than assembling it by hand — the IRIs in a response are authoritative.</p><p>For runtime slot availability (a date-specific list of bookable times) see the dedicated <a href="/api/rest-api/shop/products/get-booking-slots.html">Booking Slots</a> page — it&#39;s separate from the static <strong>slot config</strong> endpoints documented here.</p><h2 id="endpoints-in-this-group" tabindex="-1">Endpoints in this group <a class="header-anchor" href="#endpoints-in-this-group" aria-label="Permalink to &quot;Endpoints in this group&quot;">​</a></h2><h3 id="variants-configurable-type" tabindex="-1">Variants (configurable type) <a class="header-anchor" href="#variants-configurable-type" aria-label="Permalink to &quot;Variants (configurable type)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/variants</code></td><td>Child variants of a configurable parent</td></tr></tbody></table><h3 id="booking-products-booking-type-—-slot-config" tabindex="-1">Booking Products (booking type — slot config) <a class="header-anchor" href="#booking-products-booking-type-—-slot-config" aria-label="Permalink to &quot;Booking Products (booking type — slot config)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/booking-products</code></td><td>Booking config rows for a product</td></tr><tr><td>GET</td><td><code>/api/shop/booking-products/{id}</code></td><td>Single booking config (with slot IRIs)</td></tr></tbody></table><h3 id="booking-slot-configs-one-model-per-type" tabindex="-1">Booking Slot Configs (one model per type) <a class="header-anchor" href="#booking-slot-configs-one-model-per-type" aria-label="Permalink to &quot;Booking Slot Configs (one model per type)&quot;">​</a></h3><p>These are the <strong>static configuration rows</strong> referenced by the <code>defaultSlot</code> / <code>appointmentSlot</code> / <code>rentalSlot</code> / <code>tableSlot</code> / <code>eventTickets[]</code> IRIs on a <code>BookingProduct</code>. They describe the schedule template — not the per-date runtime slots.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>For booking type</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/booking_product_default_slots</code></td><td><code>default</code></td></tr><tr><td>GET</td><td><code>/api/shop/booking_product_default_slots/{id}</code></td><td><code>default</code></td></tr><tr><td>GET</td><td><code>/api/shop/booking_product_appointment_slots</code></td><td><code>appointment</code></td></tr><tr><td>GET</td><td><code>/api/shop/booking_product_appointment_slots/{id}</code></td><td><code>appointment</code></td></tr><tr><td>GET</td><td><code>/api/shop/booking_product_rental_slots</code></td><td><code>rental</code></td></tr><tr><td>GET</td><td><code>/api/shop/booking_product_rental_slots/{id}</code></td><td><code>rental</code></td></tr><tr><td>GET</td><td><code>/api/shop/booking_product_table_slots</code></td><td><code>table</code></td></tr><tr><td>GET</td><td><code>/api/shop/booking_product_table_slots/{id}</code></td><td><code>table</code></td></tr><tr><td>GET</td><td><code>/api/shop/booking_product_event_tickets</code></td><td><code>event</code> (tickets)</td></tr><tr><td>GET</td><td><code>/api/shop/booking_product_event_tickets/{id}</code></td><td><code>event</code> (tickets)</td></tr></tbody></table><h3 id="bundle-options-member-products-translations-bundle-type" tabindex="-1">Bundle Options + Member Products + Translations (bundle type) <a class="header-anchor" href="#bundle-options-member-products-translations-bundle-type" aria-label="Permalink to &quot;Bundle Options + Member Products + Translations (bundle type)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/bundle-options</code></td><td>Decision groups for a bundle (nested)</td></tr><tr><td>GET</td><td><code>/api/shop/product_bundle_options/{id}</code></td><td>Single bundle option</td></tr><tr><td>GET</td><td><code>/api/shop/product-bundle-option-products</code></td><td>Paginated list of every member-row</td></tr><tr><td>GET</td><td><code>/api/shop/product-bundle-option-products/{id}</code></td><td>Single member-row by global ID</td></tr><tr><td>GET</td><td><code>/api/shop/product_bundle_option_translations</code></td><td>Paginated locale labels</td></tr><tr><td>GET</td><td><code>/api/shop/product_bundle_option_translations/{id}</code></td><td>Single label</td></tr></tbody></table><h3 id="grouped-products-grouped-type" tabindex="-1">Grouped Products (grouped type) <a class="header-anchor" href="#grouped-products-grouped-type" aria-label="Permalink to &quot;Grouped Products (grouped type)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/grouped-products</code></td><td>Members of a grouped product (nested)</td></tr><tr><td>GET</td><td><code>/api/shop/product_grouped_products/{id}</code></td><td>Single grouped-product association</td></tr></tbody></table><h3 id="downloadable-links-samples-translations-downloadable-type" tabindex="-1">Downloadable Links + Samples + Translations (downloadable type) <a class="header-anchor" href="#downloadable-links-samples-translations-downloadable-type" aria-label="Permalink to &quot;Downloadable Links + Samples + Translations (downloadable type)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/downloadable-links</code></td><td>Purchasable links for a product</td></tr><tr><td>GET</td><td><code>/api/shop/product-downloadable-links</code></td><td>Paginated root collection</td></tr><tr><td>GET</td><td><code>/api/shop/product-downloadable-links/{id}</code></td><td>Single link</td></tr><tr><td>GET</td><td><code>/api/shop/product_downloadable_link_translations</code></td><td>Paginated locale labels</td></tr><tr><td>GET</td><td><code>/api/shop/product_downloadable_link_translations/{id}</code></td><td>Single label</td></tr><tr><td>GET</td><td><code>/api/shop/products/{productId}/downloadable-samples</code></td><td>Preview samples for a product</td></tr><tr><td>GET</td><td><code>/api/shop/product-downloadable-samples</code></td><td>Paginated root collection</td></tr><tr><td>GET</td><td><code>/api/shop/product-downloadable-samples/{id}</code></td><td>Single sample</td></tr><tr><td>GET</td><td><code>/api/shop/product_downloadable_sample_translations</code></td><td>Paginated locale labels</td></tr><tr><td>GET</td><td><code>/api/shop/product_downloadable_sample_translations/{id}</code></td><td>Single label</td></tr></tbody></table><h2 id="response-field-reference-key-shapes" tabindex="-1">Response field reference (key shapes) <a class="header-anchor" href="#response-field-reference-key-shapes" aria-label="Permalink to &quot;Response field reference (key shapes)&quot;">​</a></h2><h3 id="variant" tabindex="-1">Variant <a class="header-anchor" href="#variant" aria-label="Permalink to &quot;Variant&quot;">​</a></h3><p>Same shape as a card-level <a href="/api/rest-api/shop/products/get-products.html#card-level-fields">Product</a> — variants are themselves <code>simple</code> products.</p><h3 id="booking-product" tabindex="-1">Booking Product <a class="header-anchor" href="#booking-product" aria-label="Permalink to &quot;Booking Product&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Booking config row ID — pass to <code>/booking-slots?id=…</code> for runtime availability</td></tr><tr><td><code>type</code></td><td>string</td><td><code>default</code>, <code>appointment</code>, <code>rental</code>, <code>event</code>, <code>table</code></td></tr><tr><td><code>qty</code></td><td>integer</td><td>Total capacity (where applicable)</td></tr><tr><td><code>location</code></td><td>string</td><td>Physical location for in-person bookings</td></tr><tr><td><code>showLocation</code></td><td>boolean (0/1)</td><td>Whether to show <code>location</code> to the customer</td></tr><tr><td><code>availableFrom</code> / <code>availableTo</code></td><td>string (ISO)</td><td>Allowed booking window</td></tr><tr><td><code>slots</code></td><td>object | null</td><td>Inline preview of the schedule template (also reachable via the type-specific IRI)</td></tr><tr><td><code>defaultSlot</code> / <code>appointmentSlot</code> / <code>rentalSlot</code> / <code>tableSlot</code></td><td>string (IRI) | null</td><td>Type-specific config IRI — only one is non-null per row</td></tr><tr><td><code>eventTickets</code></td><td>array</td><td>For <code>event</code> type — list of ticket rows</td></tr></tbody></table><h3 id="booking-slot-config-default-appointment-rental-table" tabindex="-1">Booking Slot Config (default / appointment / rental / table) <a class="header-anchor" href="#booking-slot-config-default-appointment-rental-table" aria-label="Permalink to &quot;Booking Slot Config (default / appointment / rental / table)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Config primary key</td></tr><tr><td><code>bookingType</code></td><td>string</td><td><code>one</code> (single slot per day), <code>many</code> (multiple slots per day)</td></tr><tr><td><code>duration</code></td><td>integer | null</td><td>Slot length in minutes</td></tr><tr><td><code>breakTime</code></td><td>integer | null</td><td>Gap between slots in minutes</td></tr><tr><td><code>slots</code></td><td>string (JSON)</td><td>Schedule template. <strong>JSON-encoded string</strong> — <code>JSON.parse()</code> on the client</td></tr></tbody></table><h3 id="booking-event-ticket" tabindex="-1">Booking Event Ticket <a class="header-anchor" href="#booking-event-ticket" aria-label="Permalink to &quot;Booking Event Ticket&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Ticket primary key</td></tr><tr><td><code>bookingProductId</code></td><td>integer</td><td>Owning booking product</td></tr><tr><td><code>price</code></td><td>number</td><td>Ticket price</td></tr><tr><td><code>qty</code></td><td>integer</td><td>Ticket inventory</td></tr><tr><td><code>specialPrice</code></td><td>number | null</td><td>Sale price</td></tr><tr><td><code>specialPriceFrom</code> / <code>specialPriceTo</code></td><td>string | null</td><td>Sale window</td></tr><tr><td><code>formattedPrice</code> / <code>formattedSpecialPrice</code></td><td>string | null</td><td>Currency-formatted strings</td></tr><tr><td><code>translation</code> / <code>translations</code></td><td>IRI / array</td><td>Locale-specific <code>name</code> and <code>description</code></td></tr></tbody></table><h3 id="bundle-option" tabindex="-1">Bundle Option <a class="header-anchor" href="#bundle-option" aria-label="Permalink to &quot;Bundle Option&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Option primary key</td></tr><tr><td><code>type</code></td><td>string</td><td><code>radio</code>, <code>checkbox</code>, <code>select</code>, <code>multi</code></td></tr><tr><td><code>isRequired</code></td><td>boolean (0/1)</td><td>Whether the customer must pick at least one member</td></tr><tr><td><code>sortOrder</code></td><td>integer</td><td>Display order</td></tr><tr><td><code>product</code></td><td>string (IRI)</td><td>Parent bundle product</td></tr><tr><td><code>bundleOptionProducts</code></td><td>array (IRI)</td><td>Member rows — dereference for actual SKUs</td></tr><tr><td><code>translation</code></td><td>string (IRI)</td><td>Locale-specific label</td></tr><tr><td><code>translations</code></td><td>array (IRI)</td><td>All locale labels</td></tr></tbody></table><h3 id="bundle-option-product" tabindex="-1">Bundle Option Product <a class="header-anchor" href="#bundle-option-product" aria-label="Permalink to &quot;Bundle Option Product&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Member row primary key</td></tr><tr><td><code>qty</code></td><td>integer</td><td>Default quantity contributed when this member is selected</td></tr><tr><td><code>isUserDefined</code></td><td>boolean (0/1)</td><td>Whether the customer can change <code>qty</code></td></tr><tr><td><code>isDefault</code></td><td>boolean (0/1)</td><td>Whether the member is pre-selected on the PDP</td></tr><tr><td><code>sortOrder</code></td><td>integer</td><td>Display order</td></tr><tr><td><code>bundleOption</code></td><td>string (IRI)</td><td>Parent bundle option</td></tr><tr><td><code>product</code></td><td>string (IRI)</td><td>Member SKU — dereference for full product details</td></tr></tbody></table><h3 id="grouped-product" tabindex="-1">Grouped Product <a class="header-anchor" href="#grouped-product" aria-label="Permalink to &quot;Grouped Product&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Association primary key</td></tr><tr><td><code>qty</code></td><td>integer</td><td>Default quantity</td></tr><tr><td><code>sortOrder</code></td><td>integer</td><td>Display order</td></tr><tr><td><code>product</code></td><td>string (IRI)</td><td>Parent grouped product</td></tr><tr><td><code>associatedProduct</code></td><td>string (IRI)</td><td>The simple product associated with the group</td></tr></tbody></table><h3 id="downloadable-link" tabindex="-1">Downloadable Link <a class="header-anchor" href="#downloadable-link" aria-label="Permalink to &quot;Downloadable Link&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Link primary key</td></tr><tr><td><code>url</code></td><td>string | null</td><td>Externally-hosted file URL (<code>type = url</code>)</td></tr><tr><td><code>type</code></td><td>string</td><td><code>file</code> (uploaded) or <code>url</code> (external)</td></tr><tr><td><code>price</code></td><td>number</td><td>Per-link price</td></tr><tr><td><code>formattedPrice</code></td><td>string</td><td>Currency-formatted</td></tr><tr><td><code>sampleFile</code></td><td>string | null</td><td>Sample file storage path</td></tr><tr><td><code>sampleFileName</code></td><td>string | null</td><td>Original filename</td></tr><tr><td><code>sampleType</code></td><td>string | null</td><td><code>file</code> or <code>url</code></td></tr><tr><td><code>downloads</code></td><td>integer</td><td>Download cap per purchase</td></tr><tr><td><code>sortOrder</code></td><td>integer</td><td>Display order</td></tr><tr><td><code>fileUrl</code></td><td>string</td><td>Public URL for the actual purchasable file</td></tr><tr><td><code>sampleFileUrl</code></td><td>string</td><td>Public URL for the preview</td></tr><tr><td><code>product</code></td><td>string (IRI)</td><td>Parent product</td></tr><tr><td><code>translation</code></td><td>string (IRI)</td><td>Locale-specific name + description</td></tr><tr><td><code>translations</code></td><td>array (IRI)</td><td>All locale translations</td></tr></tbody></table><h3 id="downloadable-sample" tabindex="-1">Downloadable Sample <a class="header-anchor" href="#downloadable-sample" aria-label="Permalink to &quot;Downloadable Sample&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Sample primary key</td></tr><tr><td><code>file</code></td><td>string</td><td>Storage path</td></tr><tr><td><code>fileName</code></td><td>string</td><td>Original filename</td></tr><tr><td><code>type</code></td><td>string</td><td><code>file</code> or <code>url</code></td></tr><tr><td><code>sortOrder</code></td><td>integer</td><td>Display order</td></tr><tr><td><code>fileUrl</code></td><td>string</td><td>Public URL for the preview</td></tr><tr><td><code>product</code></td><td>string (IRI)</td><td>Parent product</td></tr><tr><td><code>translation</code> / <code>translations</code></td><td>IRI / array</td><td>Locale-specific labels</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Variant picker on a configurable PDP</strong> — the parent&#39;s <code>superAttributes[]</code> describes the dimensions; <code>GET /products/{id}/variants</code> returns the inventory of combinations.</li><li><strong>Booking flow</strong> — fetch <code>/products/{id}/booking-products</code> for the schedule template, then <code>/booking-slots?id=…&amp;date=…</code> for the actual selectable times on a date.</li><li><strong>Event ticket purchase</strong> — read <code>eventTickets[]</code> from the booking-product response; each row is its own purchasable line with its own qty and price.</li><li><strong>Bundle builder</strong> — walk <code>bundleOptions[]</code> for the groups, dereference each <code>bundleOptionProducts[]</code> IRI for member details.</li><li><strong>Grouped product cart row</strong> — list members from <code>/products/{id}/grouped-products</code>, render a qty input per <code>associatedProduct</code>.</li><li><strong>Downloadable PDP</strong> — paid <code>downloadableLinks</code> and free <code>downloadableSamples</code> are separate lists; show the sample download button next to the paid link.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/products/get-product.html">Single Product</a> — embeds <code>variants</code>, <code>bookingProducts</code>, <code>bundleOptions</code>, <code>groupedProducts</code>, <code>downloadableLinks</code>, <code>downloadableSamples</code> inline</li><li><a href="/api/rest-api/shop/products/get-booking-slots.html">Booking Slots</a> — date-specific runtime availability</li><li><a href="/api/rest-api/shop/products/product-subresources.html">Product Sub-Resources</a> — the <code>Product</code> tag (images, videos, customer-group prices, customizable options, attribute values)</li><li><a href="/api/rest-api/introduction.html#iris-hateoas">Introduction → IRIs &amp; HATEOAS</a> — how to dereference the path references in these payloads</li></ul>',44)]))}const b=e(a,[["render",n]]);export{h as __pageData,b as default};
